#!/usr/bin/env node
/**
 * Vectrex Studio MCP server (stdio).
 *
 * Speaks the Model Context Protocol on stdin/stdout (newline-delimited JSON-RPC 2.0)
 * and forwards tool calls to the running Vectrex Studio IDE over an authenticated
 * localhost TCP connection.
 *
 *   MCP client (Claude Code, ...) ⇄ stdio ⇄ this process ⇄ TCP 127.0.0.1 ⇄ IDE main process
 *
 * Configuration (environment):
 *   VECTREX_STUDIO_MCP_PORT   TCP port the IDE listens on (default 9123)
 *   VECTREX_STUDIO_MCP_TOKEN  auth token generated by the IDE at startup (required)
 *   MCP_VERBOSE=1             log to stderr
 *
 * The IDE hands out both values itself (getMcpLaunchSpec() in the Electron main
 * process). The tool list is fetched FROM the IDE ('ide/list_tools'), so it always
 * matches what the IDE implements; only get_project_docs is served locally.
 *
 * No dependencies. Runs under plain Node >= 18 and under Electron as Node
 * (ELECTRON_RUN_AS_NODE=1 <electron> server.js).
 */
'use strict';

const net = require('net');

const SERVER_NAME = 'vectrex-studio';
const SERVER_VERSION = '1.0.0';
const SUPPORTED_PROTOCOL_VERSIONS = ['2025-06-18', '2025-03-26', '2024-11-05'];

const PORT = (() => {
  const n = parseInt(process.env.VECTREX_STUDIO_MCP_PORT || '', 10);
  return Number.isInteger(n) && n > 0 && n < 65536 ? n : 9123;
})();
const TOKEN = process.env.VECTREX_STUDIO_MCP_TOKEN || '';
const HOST = '127.0.0.1';
const VERBOSE = process.env.MCP_VERBOSE === '1';

const CONNECT_TIMEOUT_MS = 2000;
const DEFAULT_CALL_TIMEOUT_MS = 30000;
const LONG_CALL_TIMEOUT_MS = 180000;
// A build through ide/run can download the SDK / pico-sdk and run a full C toolchain.
const BUILD_CALL_TIMEOUT_MS = 900000;
const LONG_METHODS = new Set(['compiler/build', 'compiler/build_and_run', 'debugger/start', 'emulator/run', 'project/open', 'project/create', 'ide/get_context']);
const BUILD_METHODS = new Set(['ide/run', 'compiler/build', 'compiler/build_and_run', 'cartridge/upload']);
const INSTRUCTIONS_TIMEOUT_MS = 3000;

// Used only when the IDE cannot be reached at initialize time. The real text is the IDE's
// (ide/electron/src/mcp/instructions.ts, served as 'ide/get_instructions').
const FALLBACK_INSTRUCTIONS =
  'You are running inside Vectrex Studio, a development environment for the Vectrex console ' +
  '(VPy language, C projects on the uvmc2-sdk, emulators). Its tools drive the IDE: do the work through ' +
  'them (project_create/project_open, project_write_file, ide_run to build and run in the emulator) ' +
  'instead of improvising other routes (no generated images, no ad-hoc scripts or sleeps). ' +
  'Call ide_get_context first: it lists the project\'s assets and its language API. Create art/sound/levels as assets ' +
  '(asset_create), and look the API up with api_reference, never by grepping the SDK or compiler sources. ' +
  'The IDE is not reachable right now: ask the user to start Vectrex Studio, ' +
  'and run claude from its integrated terminal. get_project_docs works offline.';
const BACKOFF_MIN_MS = 1000;
const BACKOFF_MAX_MS = 30000;

function log(...args) {
  if (VERBOSE) console.error('[vectrex-studio-mcp]', ...args);
}

// ─────────────────────────────────────────────────────────────────────────────
// IDE connection
// ─────────────────────────────────────────────────────────────────────────────

class IdeConnection {
  constructor({ host, port, token, onUp }) {
    this.host = host;
    this.port = port;
    this.token = token;
    this.onUp = onUp || (() => {});
    this.socket = null;
    this.ready = false;
    this.connecting = null;
    this.pending = new Map(); // id -> { resolve, reject, timer }
    this.nextId = 1;
    this.lastError = null;
    this.authRejected = false;
    this.backoff = BACKOFF_MIN_MS;
    this.retryTimer = null;
    this.closed = false;
  }

  /** Connect + authenticate once. Resolves true/false; never throws. */
  connect() {
    if (this.ready) return Promise.resolve(true);
    if (this.connecting) return this.connecting;
    this.connecting = new Promise((resolve) => {
      let settled = false;
      let buffer = '';
      const socket = net.createConnection({ host: this.host, port: this.port });
      socket.setEncoding('utf8');
      socket.setNoDelay(true);

      const finish = (ok, err) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        this.connecting = null;
        if (ok) {
          this.socket = socket;
          this.ready = true;
          this.lastError = null;
          this.authRejected = false;
          this.backoff = BACKOFF_MIN_MS;
          log(`connected to IDE on ${this.host}:${this.port}`);
          try { this.onUp(); } catch (e) { log('onUp failed:', e && e.message); }
        } else {
          this.lastError = err;
          socket.destroy();
          log('connect failed:', err);
        }
        resolve(ok);
      };

      const timer = setTimeout(() => finish(false, `timed out connecting to ${this.host}:${this.port}`), CONNECT_TIMEOUT_MS);

      socket.on('connect', () => {
        socket.write(JSON.stringify({ jsonrpc: '2.0', id: 0, method: 'auth', params: { token: this.token } }) + '\n');
      });

      socket.on('data', (chunk) => {
        buffer += chunk;
        let nl;
        while ((nl = buffer.indexOf('\n')) !== -1) {
          const line = buffer.slice(0, nl).trim();
          buffer = buffer.slice(nl + 1);
          if (!line) continue;
          let msg;
          try { msg = JSON.parse(line); } catch (e) { log('bad line from IDE:', line.slice(0, 200)); continue; }
          if (!settled) {
            // First reply is the auth reply.
            if (msg && msg.result && msg.result.ok) finish(true);
            else {
              this.authRejected = true;
              finish(false, `authentication rejected by the IDE: ${(msg && msg.error && msg.error.message) || 'unknown error'}`);
            }
            continue;
          }
          this._dispatch(msg);
        }
      });

      socket.on('error', (err) => {
        if (!settled) {
          const why = err && err.code === 'ECONNREFUSED' ? `nothing is listening on ${this.host}:${this.port}` : (err && err.message) || String(err);
          finish(false, why);
        } else {
          log('socket error:', err && err.message);
        }
      });

      socket.on('close', () => {
        if (!settled) { finish(false, 'connection closed during authentication'); return; }
        if (this.socket === socket) this._onDisconnected('connection to the IDE was lost');
      });
    });
    return this.connecting;
  }

  _dispatch(msg) {
    const id = msg && msg.id;
    if (id === null || id === undefined) {
      // The IDE could not tell which request this answers (e.g. it could not parse it):
      // fail every pending call instead of letting them hang until timeout.
      const why = (msg && msg.error && msg.error.message) || 'IDE returned an unmatched response';
      for (const [pid, p] of this.pending) { clearTimeout(p.timer); this.pending.delete(pid); p.reject(new Error(why)); }
      return;
    }
    const p = this.pending.get(id);
    if (!p) { log('response for unknown id', id); return; }
    this.pending.delete(id);
    clearTimeout(p.timer);
    if (msg.error) p.reject(new Error(msg.error.message || 'IDE error'));
    else p.resolve(msg.result);
  }

  _onDisconnected(reason) {
    this.ready = false;
    this.socket = null;
    this.lastError = reason;
    for (const [id, p] of this.pending) { clearTimeout(p.timer); this.pending.delete(id); p.reject(new Error(reason)); }
    this.scheduleReconnect();
  }

  /** Background reconnect with exponential backoff (1 s .. 30 s). */
  scheduleReconnect() {
    if (this.closed || this.ready || this.retryTimer) return;
    const delay = this.backoff;
    this.backoff = Math.min(this.backoff * 2, BACKOFF_MAX_MS);
    this.retryTimer = setTimeout(async () => {
      this.retryTimer = null;
      const ok = await this.connect();
      if (!ok) this.scheduleReconnect();
    }, delay);
    if (this.retryTimer.unref) this.retryTimer.unref();
  }

  /** Human-readable reason the IDE cannot be used right now. */
  unavailableMessage() {
    if (!this.token) {
      return 'Vectrex Studio MCP token missing: VECTREX_STUDIO_MCP_TOKEN is not set. Start this MCP server from Vectrex Studio (e.g. Claude Code in its integrated terminal) so it receives the port and token.';
    }
    if (this.authRejected) {
      return `Vectrex Studio rejected the MCP token (${this.lastError}). The IDE generates a new token each time it starts — restart this MCP client from the IDE.`;
    }
    return `Vectrex Studio is not running / not reachable on ${this.host}:${this.port}` + (this.lastError ? ` (${this.lastError})` : '') + '. Start the IDE and try again.';
  }

  /** Call an IDE method; connects first if needed. Rejects with a readable error. */
  async call(method, params, timeoutMs) {
    if (!this.ready) {
      const ok = await this.connect();
      if (!ok) {
        this.scheduleReconnect();
        const e = new Error(this.unavailableMessage());
        e.unavailable = true;
        throw e;
      }
    }
    const id = this.nextId++;
    const ms = timeoutMs || (BUILD_METHODS.has(method) ? BUILD_CALL_TIMEOUT_MS
      : LONG_METHODS.has(method) ? LONG_CALL_TIMEOUT_MS : DEFAULT_CALL_TIMEOUT_MS);
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(new Error(`Vectrex Studio did not answer ${method} within ${Math.round(ms / 1000)} s`));
      }, ms);
      this.pending.set(id, { resolve, reject, timer });
      try {
        this.socket.write(JSON.stringify({ jsonrpc: '2.0', id, method, params: params || {} }) + '\n');
      } catch (e) {
        clearTimeout(timer);
        this.pending.delete(id);
        reject(new Error(`Failed to send to Vectrex Studio: ${e.message}`));
      }
    });
  }

  close() {
    this.closed = true;
    if (this.retryTimer) clearTimeout(this.retryTimer);
    if (this.socket) this.socket.destroy();
  }
}

// ============================================================
// PROJECT DOCUMENTATION - served by get_project_docs tool
// ============================================================
function getProjectDocs(topic) {
  const docs = {

    compiler: `## VPy Compiler - Critical Rules
- NEVER write WAIT_RECAL() manually - compiler auto-injects at start of loop()
- NEVER write MUSIC_UPDATE() or AUDIO_UPDATE() - auto-injected at END of loop()
- Variables in main() are NOT accessible in loop() - separate scopes
- Declare variables inside loop() where they are used
- Build and run through the IDE (ide_run); the IDE runs vpy_cli (build --target m6809|rp2350|pitrex|uvm2) itself
- Inspect generated assembly (debugging the compiler): vpy_cli asm program.vpy -o program.asm
- Compiler: buildtools/ (9 phases, one crate each); only the linker (Phase 7) computes final addresses
- Single-bank: fits in 32KB. Multibank needs META ROM_TOTAL_SIZE + ROM_BANK_SIZE
- Architecture: loop() compiles to LOOP_BODY subroutine, called via JSR from main loop
- Source: buildtools/vpy_codegen/src/m6809/mod.rs (main codegen), buildtools/vpy_codegen/src/m6809/functions.rs (MAIN/LOOP_BODY), buildtools/vpy_codegen/src/m6809/builtins.rs`,

    bios: `## BIOS Usage Rules
- NEVER use synthetic BIOS - always use real bios.bin
- Primary path: ide/frontend/src/assets/bios.bin
- Legacy path: ide/frontend/dist/bios.bin  
- BIOS boots automatically to Minestorm (no button press needed)
- BIOS always jumps to $0000 (Bank #0) - NEVER uses RESET vector at $FFFE
- record_bios_call: only registers JSR/BSR toward >= 0xF000, no fake side effects
- Key BIOS addresses: Wait_Recal=0xF192, Draw_Line_d=0xF2B2, Print_Str_d=0xF373
- DP must be set to $D0 before most BIOS calls (compiler handles this)`,

    tests: `## Tests Structure & Rules
- tests/opcodes/ - MC6809 opcode tests (arithmetic, branch, comparison, data_transfer, logic, register, stack)
- tests/components/ - emulator component tests (integration, hardware, engine, memory, cpu)
- RAM in tests: 0xC800-0xCFFF. Stack: 0xCFFF. One file per opcode.
- NEVER use synthetic BIOS in tests
- Always verify: registers, flags, cycles after each opcode
- cargo test -p vectrex_emulator after any CPU/WASM API changes`,

    assets: `## Assets (full reference: docs/ASSETS.md)
The IDE is asset-driven: sprites, music, sound effects, animations, levels and enemies are JSON
files the user edits in the IDE's editors (Vector, Music, SFX, Animation, Enemy, Instrument,
Mesh, Scene and 3D Animation editors; the Playground for levels). Do not hard-code them in code (no DRAW_LINE sprite lists,
raw PSG writes or level tables). With the IDE running:
- assets_list: the project's assets + the exact code that uses each one
- asset_get_format {type}: fields + a minimal valid example
- asset_create {type, name, content}: writes it to the right folder and compiles it
The name in code = file name without extension. Create referenced assets first.

type    folder               VPy                                              C (#include "<name>.h")
.vec    assets/vectors       DRAW_VECTOR("n", x, y)  DRAW_VECTOR_EX("n", x, y, mirror, intensity)
                             DRAW_VECTOR_3D("n", ax, ay, az, x, y) (points with z)  DRAW_VECTOR(N_vec, x, y)
.vmus   assets/music         PLAY_MUSIC("n")  STOP_MUSIC()                       PLAY_MUSIC(N_music)
.vsfx   assets/sfx           PLAY_SFX("n")                                       PLAY_SFX(N_sfx)
.vanim  assets/animations    DRAW_ANIM("n", x, y, mirror)                        DRAW_ANIM(N_anim, N_anim_sprites, x, y, mirror)
.vplay  assets/playground    LOAD_LEVEL("n") (main)  SHOW_LEVEL() (loop)          LOAD_LEVEL(N_level, N_level_sprites)  SHOW_LEVEL()
.venemy assets/enemies       placed by a level; SPAWN_ENEMIES("level"), UPDATE_ENEMIES(), DRAW_ENEMIES()
                                                                                 SPAWN_ENEMIES(L_enemies, L_enemy_sprites)
.vinstr assets/instruments   PLAY_NOTE("n", channel, midi_note)                  PLAY_NOTE(N_instr, channel, midi_note)
.vrec   assets/recordings    DRAW_RECORDING("n", x, y, scale 128=100%, frame)    DRAW_RECORDING(N_vrec, x, y, scale, frame)
.vsmp   assets/samples       PLAY_SAMPLE("n"), SAMPLE_POS(fps) - not on m6809    PLAY_SAMPLE(N_smp)
.vmesh  assets/meshes        LOAD_MESH("n"), DRAW_MESH("n", xf, br) - uvm2 only   vpy3d_load_mesh(&m, N_vmesh)
.vscene assets/scenes        LOAD_SCENE("n"), DRAW_SCENE("n", x, y, z, br) - uvm2 only
                                                        vpy3d_load_scene(&s, N_vscene, N_vscene_meshes)  vpy3d_draw_scene
.vskel  assets/skeletons     import n -> n.T_BONES, n.T_TURNS, n.T_BONE_MESHES... (uvm2: BONE_ADD/BONE_ROT)
                                                                                 N_T_BONES, N_T_TURNS... (vpybone)
.vclip  assets/clips         import n -> n.T_POSES[n.POSE_X][n.JOINT_Y], n.T_CLIPS, n.T_KEYS, n.T_SET_CLIPS
                                                                                 N_T_POSES[N_POSE_X][N_JOINT_Y]...
N = the name upper-cased with "-" -> "_".

### .vec (JSON): coordinates -127..127 around the sprite centre, +Y up
{"version":"1.0","name":"ship","canvas":{"width":256,"height":256,"origin":"center"},
 "layers":[{"name":"default","visible":true,"paths":[{"name":"hull","intensity":127,"closed":true,
   "points":[{"x":0,"y":12},{"x":-10,"y":-8},{"x":10,"y":-8}]}]}]}

### .vmus (JSON): "id" required on every note/noise event
{"version":"1.0","name":"theme","author":"","tempo":120,"ticksPerBeat":24,"totalTicks":96,
 "notes":[{"id":"n1","note":60,"start":0,"duration":24,"velocity":12,"channel":0}],
 "noise":[{"id":"h1","start":0,"duration":6,"period":8,"channels":2,"velocity":5}],
 "loopStart":0,"loopEnd":96}
- note: MIDI (60=C4). velocity 0-15. channel 0-2 (PSG A/B/C; SFX play on C). noise period 0-31, channels bitmask 1=A 2=B 4=C

### .vmesh (JSON, C only): faces and/or scenery
{"name":"room","hard":45,"vertices":[{"x","y","z"}],"faces":[[0,3,2,1]],
 "lines":[{"points":[{"x":0,"y":0,"z":0},{"x":40000,"y":0,"z":0}],"br":70,"closed":false,"fog":true}],
 "occluders":[{"points":[3 to 8 corners of a convex solid]}]}
- needs faces (with vertices), "sections" (lofting), lines or occluders. Vertices are i16; line/occluder points +-1000000.
- lines: 2+ points, br 1..100 (% of the mesh brightness), fog false = ignores the scenery fog. Occluders are never drawn: they hide what is drawn after the mesh.

### .vscene (JSON, C only, SDK v1.3.5+): a set of .vmesh pieces placed from the game's pos[3]
{"name":"tunnel","fog":{"full":3000,"gone":17500},"groups":["alarm"],
 "items":[{"name":"ribs","mesh":"rib","at":{"z":600},"follow":{"z":-1},"repeat":{"axis":"z","step":2000,"count":9}},
          {"mesh":["low","high"],"at":{"z":600},"follow":{"z":-1},"repeat":{"step":2000,"count":9},"window":{"max":10999},"br":75},
          {"mesh":"lights","group":"!alarm","fog":"whole"}]}
- mesh = assets/meshes/<name>.vmesh (a list only with repeat: copies take turns); <= 16 meshes. at: whole numbers; follow: factor of pos per axis.
- Items draw in order (near first). fog true|false|"whole". group bit n = n-th name in groups; "!name" inverts.
- C: vpy3d_load_scene(&s, N_vscene, N_vscene_meshes); vpy3d_draw_scene(&s, 0, pos, groups_mask, br). SRCS += $(VPY_C_SDK)/vpy3d.c`,

    joystick: `## Joystick Input
- J1_X(), J1_Y(): signed analog axis, about -128..127 (0 = centre, +Y up). Use a dead zone: if J1_X() > 20: ...
- Read from the BIOS cells Vec_Joy_1_X/Y ($C81B/$C81C); the compiler injects ONE Joy_Analog call per frame at the top of loop() when the code reads an axis — never call it yourself
- Joystick 2: J2_X(), J2_Y(). Buttons: topic "buttons"
- Source: buildtools/vpy_codegen/src/m6809/joystick.rs (J1X_BUILTIN/J1Y_BUILTIN), buildtools/vpy_codegen/src/m6809/functions.rs (Joy_Analog injection)`,

    buttons: `## Button System (J1_BUTTON_1-4) - Auto-injected
- NEVER call UPDATE_BUTTONS() - compiler auto-injects Read_Btns at start of loop()
- J1_BUTTON_1() through J1_BUTTON_4() return 0=released, 1=pressed
- Auto-injection sequence at loop start: JSR DP_to_D0 → JSR Read_Btns → JSR DP_to_C8
- Buttons read cached $C80F (Vec_Btn_State) - set once per frame, no auto-fire
- Why one Read_Btns per frame: multiple calls break Vec_Prev_Btns debounce
- Source: buildtools/vpy_codegen/src/m6809/functions.rs (Read_Btns auto-injection in LOOP_BODY)
         buildtools/vpy_codegen/src/m6809/builtins.rs (J1_BUTTON_* handlers)`,

    const_arrays: `## Const Arrays - ROM-Only Data
- const keyword: allocates in ROM, zero RAM overhead
- Syntax: const player_x = [10, 20, 30]  (NOT let)
- Indexing: val = player_x[0] or val = player_x[index]  (both work)
- Const string arrays: const names = ["HELLO", "WORLD"] - indexing returns pointer
  - Use with PRINT_TEXT: PRINT_TEXT(x, y, names[i])
- Regular arrays (let) allocate RAM pointer + init code in main()
- Const arrays emit ARRAY_<NAME>_DATA labels in ROM; MAIN sets the array pointer to that ROM label
- Source: buildtools/vpy_codegen/src/m6809/variables.rs (array data emission)
         buildtools/vpy_codegen/src/m6809/functions.rs (const array pointer init in MAIN)
         buildtools/vpy_codegen/src/m6809/expressions.rs (indexing)`,

    modules: `## Module System (Phase 6.3 Complete)
- Import: import input  then call input.get_input() or access input.var_name[i]
- Unifier transforms dot notation: input.get_input() → INPUT_GET_INPUT()
- Helpers auto-deduplicated (unifier merges all imports into one module before codegen)
- Build: cargo run --bin vpy_cli -- build project.vpyproj -o game.bin (auto-resolves imports)
- Example: examples/multi-module/
- Source: buildtools/vpy_unifier/src/lib.rs (dot notation rewriting), buildtools/vpy_unifier/src/resolver.rs (symbol resolution)`,

    banking: `## Multibank ROM Architecture
- Meta required: META ROM_TOTAL_SIZE = 524288 and META ROM_BANK_SIZE = 16384
- Banks 0..N-2 are switched in at $0000-$3FFF; the last bank (helpers, = total/bank_size - 1) is fixed at $4000-$7FFF
- Every bank is assembled with ORG $0000. Tested configuration: 4 banks × 16KB (64KB); >4 banks compiles but cross-bank resolution is incomplete
- Bank switch register: $DF00 (write bank ID). NEVER $4000 or $D000.
- Boot: BIOS → $0000 (Bank #0). MAIN and LOOP_BODY live in Bank #0.
- CRITICAL: BIOS always jumps to $0000, NEVER to RESET vector.
- Cross-bank calls auto-wrapped (save bank → switch → call → restore); CURRENT_ROM_BANK RAM tracker
- Source: buildtools/vpy_bank_allocator/src/ (allocator.rs, graph.rs), buildtools/vpy_codegen/src/m6809/functions.rs (generate_functions_by_bank),
         buildtools/vpy_linker/src/multi_bank_linker.rs (per-bank assembly + ROM image)`,

    draw_line: `## DRAW_LINE Optimization
- DRAW_LINE(x0, y0, x1, y1, intensity)
- Args are stored in DRAW_LINE_ARGS (5 words) and DRAW_LINE_WRAPPER is called
- DRAW_LINE_WRAPPER (emitted only if DRAW_LINE is used): sets DP=$D0, Reset0Ref, intensity, moves to (x0,y0), draws to (x1,y1) with segmentation for long lines
- Source: buildtools/vpy_codegen/src/m6809/builtins.rs (emit_draw_line)
         buildtools/vpy_codegen/src/m6809/drawing.rs (DRAW_LINE_WRAPPER)`,

    music: `## Music System
- PLAY_MUSIC("name") - plays assets/music/name.vmus (loops); STOP_MUSIC() stops it
- PLAY_SFX("name") - one-shot assets/sfx/name.vsfx on PSG channel C; PLAY_NOTE("instr", channel, note) plays a .vinstr
- Make new tracks/effects as assets (asset_create type vmus / vsfx / vinstr), never as raw PSG writes; see topic "assets"
- AUDIO_UPDATE auto-injected at END of loop() by compiler
- PSG player updates every frame (50Hz)
- MIDI to PSG: period = 1_500_000 / (16 * freq). freq = 440 * 2^((note-69)/12)
- note 60 (C4) → PSG period 358, note 69 (A4) → period 213 (= Freq_Table[26] de la BIOS)
- PSG channels: 0=A, 1=B, 2=C. Velocity: 0-15. Noise period: 0-31.
- Source: buildtools/vpy_codegen/src/musres.rs (MusicResource), buildtools/vpy_codegen/src/m6809/functions.rs (AUDIO_UPDATE injection)`,

    meta: `## VPy META Configuration
- META TITLE = "Game Name"      - Cartridge title
- META MUSIC = 1                - Enable music system
- META ROM_TOTAL_SIZE = 524288  - Enable multibank (512KB = 32×16KB)
- META ROM_BANK_SIZE = 16384    - Bank size (always 16384 for Vectrex)
- Single bank (no ROM_TOTAL_SIZE): code must fit in 32KB
- Multibank: code auto-distributed across banks, cross-bank calls auto-wrapped`,

  };

  if (topic === 'all') {
    return Object.values(docs).join('\n\n---\n\n');
  }
  return docs[topic] || `Unknown topic '${topic}'. Available: ${Object.keys(docs).join(', ')}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Tools
// ─────────────────────────────────────────────────────────────────────────────

const DOC_TOPICS = ['assets', 'joystick', 'buttons', 'const_arrays', 'modules', 'banking', 'draw_line', 'music', 'compiler', 'bios', 'tests', 'meta', 'all'];

const LOCAL_TOOLS = [
  {
    name: 'get_project_docs',
    description: 'VPy / Vectrex reference notes by topic (compiler rules, assets, input, banking, music, ...). Works even when the IDE is not running. Topics: ' + DOC_TOPICS.join(', '),
    inputSchema: {
      type: 'object',
      properties: {
        topic: { type: 'string', enum: DOC_TOPICS, description: 'Topic name, or "all"' },
      },
      required: ['topic'],
    },
  },
];

const TOOL_NAME_RE = /^[a-zA-Z0-9_-]{1,64}$/;

class ToolRegistry {
  constructor(ide) {
    this.ide = ide;
    this.ideTools = null;        // last list fetched from the IDE: [{name, method, description, inputSchema}]
    this.methodByName = new Map();
  }

  async refresh() {
    const res = await this.ide.call('ide/list_tools', {});
    const tools = Array.isArray(res && res.tools) ? res.tools : [];
    const seen = new Set(LOCAL_TOOLS.map((t) => t.name));
    const clean = [];
    const map = new Map();
    for (const t of tools) {
      if (!t || typeof t.name !== 'string' || typeof t.method !== 'string') continue;
      if (!TOOL_NAME_RE.test(t.name) || seen.has(t.name)) { log('skipping invalid/duplicate tool', t.name); continue; }
      seen.add(t.name);
      map.set(t.name, t.method);
      clean.push({ name: t.name, description: t.description || '', inputSchema: t.inputSchema || { type: 'object', properties: {} } });
    }
    this.ideTools = clean;
    this.methodByName = map;
    return clean;
  }

  /** Tools to advertise: the IDE's list (fresh if reachable, cached otherwise) + local ones. */
  async list() {
    try {
      await this.refresh();
    } catch (e) {
      log('tools/list: IDE not reachable:', e.message);
    }
    return [...LOCAL_TOOLS, ...(this.ideTools || [])];
  }

  signature() {
    return JSON.stringify((this.ideTools || []).map((t) => t.name).sort());
  }
}

function textResult(text, isError) {
  const r = { content: [{ type: 'text', text }] };
  if (isError) r.isError = true;
  return r;
}

// ─────────────────────────────────────────────────────────────────────────────
// MCP over stdio
// ─────────────────────────────────────────────────────────────────────────────

class McpStdioServer {
  constructor(ide, registry) {
    this.ide = ide;
    this.registry = registry;
    this.initialized = false;
    this.advertised = null; // signature of the IDE tool list last given to the client
    this.buffer = '';
  }

  start() {
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => {
      this.buffer += chunk;
      let nl;
      while ((nl = this.buffer.indexOf('\n')) !== -1) {
        const line = this.buffer.slice(0, nl).replace(/\r$/, '').trim();
        this.buffer = this.buffer.slice(nl + 1);
        if (line) this.onLine(line);
      }
    });
    process.stdin.on('end', () => {
      log('stdin closed, exiting');
      this.ide.close();
      process.exit(0);
    });
  }

  send(msg) {
    process.stdout.write(JSON.stringify(msg) + '\n');
  }

  reply(id, result) { this.send({ jsonrpc: '2.0', id, result }); }
  replyError(id, code, message) { this.send({ jsonrpc: '2.0', id, error: { code, message } }); }

  /** The IDE's instructions text, or FALLBACK_INSTRUCTIONS when it cannot be reached. */
  async fetchInstructions() {
    try {
      const ok = await this.ide.connect();
      if (!ok) { this.ide.scheduleReconnect(); return FALLBACK_INSTRUCTIONS; }
      const r = await this.ide.call('ide/get_instructions', {}, INSTRUCTIONS_TIMEOUT_MS);
      if (r && typeof r.instructions === 'string' && r.instructions.trim()) return r.instructions;
      log('ide/get_instructions returned no text; using the fallback');
    } catch (e) {
      log('ide/get_instructions failed:', e && e.message);
    }
    return FALLBACK_INSTRUCTIONS;
  }

  /** Called whenever the IDE connection comes (back) up. */
  async onIdeUp() {
    if (!this.initialized) return;
    try {
      await this.registry.refresh();
      const sig = this.registry.signature();
      if (this.advertised !== null && sig !== this.advertised) {
        this.send({ jsonrpc: '2.0', method: 'notifications/tools/list_changed' });
      }
    } catch (e) {
      log('refresh after reconnect failed:', e.message);
    }
  }

  onLine(line) {
    let msg;
    try {
      msg = JSON.parse(line);
    } catch (e) {
      this.replyError(null, -32700, `Parse error: ${e.message}`);
      return;
    }
    if (Array.isArray(msg) || !msg || typeof msg !== 'object') {
      this.replyError(null, -32600, 'Invalid request');
      return;
    }
    const isRequest = Object.prototype.hasOwnProperty.call(msg, 'id') && msg.id !== null;
    if (typeof msg.method !== 'string') {
      // A response to something we sent (we send no requests) or garbage.
      if (isRequest && !('result' in msg) && !('error' in msg)) this.replyError(msg.id, -32600, 'Invalid request: missing method');
      return;
    }
    if (!isRequest) {
      this.onNotification(msg);
      return;
    }
    this.onRequest(msg).catch((e) => {
      log('internal error:', e && e.stack);
      this.replyError(msg.id, -32603, `Internal error: ${e && e.message}`);
    });
  }

  onNotification(msg) {
    if (msg.method === 'notifications/initialized') {
      this.initialized = true;
      // If the IDE was down at initialize time, tell the client once it shows up.
      if (!this.ide.ready) this.ide.scheduleReconnect();
    }
    // Other notifications (cancelled, progress, ...) need no action.
  }

  async onRequest(msg) {
    const { id, method } = msg;
    const params = msg.params && typeof msg.params === 'object' ? msg.params : {};
    switch (method) {
      case 'initialize': {
        const requested = params.protocolVersion;
        const protocolVersion = SUPPORTED_PROTOCOL_VERSIONS.includes(requested) ? requested : SUPPORTED_PROTOCOL_VERSIONS[0];
        // Connect now so the instructions (and the first tools/list) come from the IDE;
        // fall back to a short static text if it is down. Never fail initialize.
        const instructions = await this.fetchInstructions();
        this.reply(id, {
          protocolVersion,
          capabilities: { tools: { listChanged: true } },
          serverInfo: { name: SERVER_NAME, version: SERVER_VERSION },
          instructions,
        });
        return;
      }
      case 'ping':
        this.reply(id, {});
        return;
      case 'tools/list': {
        const tools = await this.registry.list();
        this.advertised = this.registry.signature();
        this.reply(id, { tools });
        return;
      }
      case 'tools/call': {
        this.reply(id, await this.callTool(params));
        return;
      }
      default:
        this.replyError(id, -32601, `Method not found: ${method}`);
    }
  }

  async callTool(params) {
    const name = params.name;
    const args = params.arguments && typeof params.arguments === 'object' ? params.arguments : {};
    if (typeof name !== 'string' || !name) return textResult('tools/call: missing tool name', true);

    if (name === 'get_project_docs') {
      const topic = typeof args.topic === 'string' ? args.topic : 'all';
      return textResult(getProjectDocs(topic), false);
    }

    let method = this.registry.methodByName.get(name);
    if (!method) {
      try {
        await this.registry.refresh();
      } catch (e) {
        return textResult(e.unavailable ? e.message : `Vectrex Studio error: ${e.message}`, true);
      }
      method = this.registry.methodByName.get(name);
      if (!method) return textResult(`Unknown tool: ${name}`, true);
    }

    try {
      const result = await this.ide.call(method, args);
      const text = typeof result === 'string' ? result : JSON.stringify(result === undefined ? null : result, null, 2);
      return textResult(text, false);
    } catch (e) {
      return textResult(e.message || String(e), true);
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Main
// ─────────────────────────────────────────────────────────────────────────────

function main() {
  let server = null;
  const ide = new IdeConnection({ host: HOST, port: PORT, token: TOKEN, onUp: () => server && server.onIdeUp() });
  const registry = new ToolRegistry(ide);
  server = new McpStdioServer(ide, registry);
  server.start();
  log(`started; IDE expected on ${HOST}:${PORT}${TOKEN ? '' : ' (no token set!)'}`);
  process.on('SIGINT', () => process.exit(0));
  process.on('SIGTERM', () => process.exit(0));
}

if (require.main === module) {
  main();
}

module.exports = { main, IdeConnection, ToolRegistry, McpStdioServer, getProjectDocs, SUPPORTED_PROTOCOL_VERSIONS, FALLBACK_INSTRUCTIONS };
